        raise ABIValueError("fixed 值必须有限，不接受 NaN 或 Infinity")
    # 有效小数位即 Decimal 指数的绝对值；Decimal('1.250') 为 3 位。
    fractional = max(0, -value.as_tuple().exponent)
    if fractional > t.scale:
        raise ABIValueError(
            f"fixed{t.bit_size}x{t.scale} 至多接受 {t.scale} 位小数，"
            f"得到 {fractional} 位：{value}"
        )
    # 乘以 10**N 只需移位指数，但低精度上下文可能舍入巨值；给出足够精度
    # 保证缩放结果精确，再以指数判断是否为整数。
    digits = len(value.as_tuple().digits)
    with localcontext() as ctx:
        ctx.prec = max(28, digits + t.scale + 10)
        scaled = value * (10 ** t.scale)
    if scaled.as_tuple().exponent < 0:
        raise ABIValueError(
            f"fixed{t.bit_size}x{t.scale} 乘以 10**{t.scale} 后必须得到整数："
            f"{value}"
        )
    integer = int(scaled)
    bits = t.bit_size
    if t.signed:
        low = -(1 << (bits - 1))
        high = (1 << (bits - 1)) - 1
        if not low <= integer <= high:
            raise ABIValueError(
                f"fixed{bits}x{t.scale} 超出补码范围 [{low}, {high}]：{value}"
            )
    else:
        if not 0 <= integer < 1 << bits:
            raise ABIValueError(
                f"ufixed{bits}x{t.scale} 超出无符号范围 "
                f"[0, {2**bits - 1}]：{value}"
            )
    return integer


